---加载资源
function MaidCoffeeSceneEnter:AsyncLoadingResources()
    cs_coroutine.yield_return(self:TransitionScene())
end

function MaidCoffeeSceneEnter:TransitionScene()
    ---场景设置信息
    self.settingVo = MaidCoffeeUtils.GetMaidCoffeeSettingVo()
    self:Preload()
    ---自定义加载进度的逻辑在此处
    local displayProgress = 0
    local toProgress      = SceneMaxProgress
    local sceneId         = self.settingVo.sceneId
    sceneManagement:Transition({ identifier = sceneId, isCache = false })
    while sceneManagement:IsTransition() do
        displayProgress = self:UpdateProgress(displayProgress, toProgress)
        yield()
    end
    self:LoadCattyPrefab()
    cs_coroutine.yield_return(self:CreatePreloadObject(displayProgress))
    self:InitWorldCanvas()
    self:LoadManagerModel()
    self:LoadClerkModel()
    --self:LoadGuestModel()
    self:LoadBusinessModel()
    if self.isNeedRefresh then
        self:LoadEventGuestModel()
    end
    self:InitMainCamSetting()
    sceneManagement:SetActive(sceneId, true)
    self._isLoadComplete = true
    if not self._isPlayOp or (not isNull(self.loadingPanel) and  self.loadingPanel:GetLoopTimes() > 0) then
        self:CloseLoading()
        self._isCloseLoading = true
    end
    yield()
end

function MaidCoffeeSceneEnter:InitWorldCanvas()
    ---@type SceneInstance
    local sceneInstance = sceneManagement:GetSceneInstance(self.settingVo.sceneId)
    local worldSpaceCanvas = sceneInstance:GetCacheObjectByName(MaidCoffeeConstants.SceneDefine.WorldSpaceCanvasName)
    KTool.SetLayer(self._layer, worldSpaceCanvas.gameObject, true)
    local canvas           = worldSpaceCanvas.gameObject:GetComponent(CanvasType)
    canvas.worldCamera     = URPCameraController.Instance.mainCamera
    ---@field worldSpaceCanvas UnityEngine.Transform
    self._worldSpaceCanvas = worldSpaceCanvas
end

function MaidCoffeeSceneEnter:LoadCattyPrefab()
    ---@type MaidCoffeeComponent
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local List = maidCoffeeComponent:GetSaveCattyRenovatedList()
    ---@type SceneInstance
    local sceneInstance = sceneManagement:GetSceneInstance(self.settingVo.sceneId)
    local scene = sceneInstance:GetCacheObjectByName("Scene")
    if not isNull(scene) then
        if not self.sceneNode then
            self.sceneNode = scene.transform:Find("ScenePartRoot")
        end
        if not self.showSuitNode then
            self.showSuitNode = scene.transform:Find("SceneShowRoot")
        end
    end

    for i, v in pairs(List) do
        local vo = MaidCoffeeUtils.GetRenovateInfoVo(v)
        self:LoadSignCattyPrefab(vo,function(_loader)
            self.typeToNode[vo.furnitureType] = _loader:Instantiate()
            _loader:Release()
            KTool.SetParent(self.typeToNode[vo.furnitureType], self.sceneNode.gameObject)
            self.typeToNode[vo.furnitureType].transform.localPosition = Vector3.New(0, 0, 0)
        end)
    end
end

function MaidCoffeeSceneEnter:LoadSignCattyPrefab(vo,callBack)
    if not isNull(vo) then
        local path = vo.prefab
        ResourceModule.LoadBundleAsync(path, function(_loader, ok, resultObject)
            if ok then
                if callBack then
                    callBack(_loader)
                end
            end
        end, true)
    end
end

--- CreatePreloadObject
---@param displayProgress number
function MaidCoffeeSceneEnter:CreatePreloadObject(displayProgress)

    ---@type SceneInstance
    local sceneInstance = sceneManagement:GetSceneInstance(self.settingVo.sceneId)
    local SceneDefine = MaidCoffeeConstants.SceneDefine
    --- 创建 场景参数配置
    local toProgress = SceneConfProgress
    self._nodeName2node = {}
    for nodeName, loader in pairs(self._sceneConfigLoaders) do
        local node = MaidCoffeeUtils.InstantiateByLoader(loader, nil, function ()
            displayProgress = self:UpdateProgress(displayProgress, toProgress)
        end)
        if not IsNull(node) then
            node.name = nodeName
            sceneInstance:AddCacheObject(node)
            self._nodeName2node[nodeName] = node
        end 
    end
    displayProgress = toProgress


    -- =========
    while RoleControllerLoader.IsAllLoadingFinish() == false do 
        coroutine.yield(Yielders.EndOfFrame)
    end 

    ---  ============================== new ================================
    toProgress = ProtagonistProgress
    local loader
    local ScenePositionsNode = self._nodeName2node[SceneDefine.ScenePositionsNode] -- "ScenePositionsNode"
    local playerPosNode = ScenePositionsNode.transform:Find(MaidCoffeeConstants.SceneDefine.SpawnMarker)
    ---
    --- ===
    

    local Vector2              = CS.UnityEngine.Vector2
    local Vector3              = CS.UnityEngine.Vector3

    DreamSpaceStates.InitInputLock()
    InputManager.Init() -- 重置, 必须在 装配 角色控制器 之前!!!  否则角色的初始朝向会被 InputManager 里的残余值修改;


    self.initLookDir = Vector3( 0, -0.1, -1 ).normalized

    local retTable = {}
    -- 正式装配 角色控制器:
    cs_coroutine.yield_return( RoleControllerLoader.AssembleRole({
        switchablePlayerPrefabPath  = "DreamSpace/Gameplay/SwitchablePlayeForLua.prefab",
        humanPrefabPath             = self.humanPath,
        ---
        initPos = playerPosNode.position,
        initRoleDir = Vector3( 0, 0, -1 ).normalized,
        initLookDir = self.initLookDir,
        initHumanScale = Vector3( 0.9, 0.9, 0.9 ), 
        vcamHeight_Human = 1.0,
        vcamRadius_Human = 1.8,
        vcamShoulderOffset_Human = Vector3.zero,
        pitchMinDegree = -50,  -- 俯仰角下界
        pitchMaxDegree = 80,   -- 俯仰角上界
        humanCapsuleRadius = 0.27, -- 等 dither 装上后可以变得更小
        isCat = false, 
        isUseManualViwRotateInPCMode = true,
        isIgnoreRunStop = true,
        isIgnoreJumpHint = true,
        isIgnoreHuman180TurnBack = true,
        isUsePiecesCollector = false,
        isUseAltKey = false,
        isHumanNeedCustomLightDirRelativeCamera = true,
    },retTable
    ))
    ---
    RoleControllerLoader.ClearLoaders() 

