function MaidCoffeeSceneEnter:InitLocationCamera(parent)
    local go = MaidCoffeeUtils.CreateVirtualCamera(MaidCoffeeConstants.SceneDefine.LocationVirtualCamera)
    local vCameraComp = KTool.GetComponent(go.gameObject, typeof(CinemachineVirtualCamera))
    assert( not isNull(vCameraComp) )
    -- 设置 fov 值, 要比 mcamera 更加靠近角色
    local lens = vCameraComp.m_Lens
    lens.FieldOfView = 30.0 -- 27 -- 适当变大点
    vCameraComp.m_Lens = lens
    vCameraComp.Priority = 110
    KTool.SetParent(go, parent.gameObject, false)
    self.virtualCamera = go
end

--- UpdateProgress
---@param displayProgress number
---@param toProgress number
function MaidCoffeeSceneEnter:UpdateProgress( displayProgress, toProgress)
    if displayProgress < toProgress then
        while displayProgress < toProgress do
            displayProgress = displayProgress + 1.5
            if not self._isPlayOp and not isNull(self.loadingPanel) then
                self.loadingPanel:__Progress(displayProgress * 0.01)
            end
            yield(Yielders.EndOfFrame)
        end
    else
        yield(Yielders.EndOfFrame)
    end
    return displayProgress
end

