function MaidCoffeeSceneEnter:LoadAnimatorControllerAndFillController(id,go,cardDojo)
    if isNull(go) then return end
    local prefabPath = MaidCoffeeUtils.GetCardAnimatorControllerPathByDojo(cardDojo)
    if prefabPath then
        local loader  = ResourceModule.LoadBundleAsync(prefabPath, nil, true)
        cs_coroutine.start(function()
            ---@type UnityEngine.Animator
            local animator = KTool.GetOrAddComponent(go, AnimatorType)
            self.curAnimator = animator
            while not loader.IsCompleted do
                yield()
            end
            if loader.IsSuccess then
                local ins = Object.Instantiate(loader.ResultObject)
                animator.runtimeAnimatorController = ins
                loader:Retain(ins)
            end
            loader:Release()
        end )
    end
end

