function MaidCoffeeSceneEnter:ClearCache()
    Physics.autoSimulation = false
    Input.multiTouchEnabled = false
    EasyTouch.SetEnable2FingersGesture(false)
    xTry(function()
        -- Physics.IgnoreLayerCollision( self._layer, self._roleLayer, self.defaultToRole )
