function MaidCoffeeSceneEnter:AutoGoToPath(params)
    local type = params.type or GoToType.MaidCoffee
    local pos,lookAtPos = self:GetGoToPosByType(type, params.eventId)
    self:AutoGoToPosition(params,pos,lookAtPos)
end

function MaidCoffeeSceneEnter:GetGoToPosByType(type,eventId)
    local posNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
    local pos ,lookAtPos
    if type == GoToType.MaidCoffee or type == GoToType.MaidCoffeeTakeOut  then
        pos = posNode.transform:Find("AutoRoute_loc/AutoRoute_Bar").gameObject.transform.position
        lookAtPos = posNode.transform:Find("manager_01").gameObject.transform.position
    elseif type == GoToType.MaidCoffeeCat or type == GoToType.MaidCoffeeCatList then
        pos = posNode.transform:Find("AutoRoute_loc/AutoRoute_Cat").gameObject.transform.position
    elseif type == GoToType.MaidCoffeeCooking then
        pos = posNode.transform:Find("AutoRoute_loc/AutoRoute_Cooking").gameObject.transform.position
    elseif type == GoToType.MaidCoffeeLounge then
        pos = posNode.transform:Find("AutoRoute_loc/AutoRoute_Lounge").gameObject.transform.position
    elseif type == GoToType.MaidCoffeeGuest then
        local guestController = self.eventGuests[eventId]
        if not isNull(guestController) then
            local index = guestController:GetGuestPosIndex()
            if not isNull(index) then
                local vo = MaidCoffeeUtils.GetGuestPathPosVo(index)
                if not isNull(vo) then
                    pos = Vector3.New(vo.xCoordinate,0,vo.zCoordinate)
                    local guestGo = guestController:GetGuestGo()
                    lookAtPos = guestGo.transform.position
                else
                    pos = Vector3.New(0,0,0)
                end
            end
        end
    elseif type == GoToType.MaidCoffeeBusiness then
        pos = posNode.transform:Find("AutoRoute_loc/AutoRoute_Business").gameObject.transform.position
    end
    return pos,lookAtPos
end
local StopDistance = 0.5
---AutoGoToPosition
---params 里面有寻路类型和回调 pos是要寻路的位置 lookAtPos表示寻路结束后要转向的位置
---@param params table
---@param pos Vector3
---@param lookAtPos Vector3
function MaidCoffeeSceneEnter:AutoGoToPosition(params,pos,lookAtPos)
    self:RemoveNavMeshAgentCo()
    self.gotoCo = cs_coroutine.start(function()
        self.isInGoToCo = true
        self.curRunMode = self.humanController.canRun
        self.humanController.canRun = true
        ---防止玩家正好在手动操作
        self.humanController:MoveEnd()
        self.humanController:MoveStart()
        -- 计算路径
        local toPos = pos
        local fromPos = self.followTF.position
        local path = CS.UnityEngine.AI.NavMeshPath()
        CS.UnityEngine.AI.NavMesh.CalculatePath(fromPos, toPos, 1, path)

        -- 寻路
        local count = path.corners.Length
        for i = 0, count - 1, 1 do
            cs_coroutine.yield_return(self:GoToPoint(path.corners[i]))
        end
        for i = 0, count - 2, 1 do
            CS.UnityEngine.Debug.DrawLine(path.corners[i], path.corners[i+1], Color.red, 2)
        end
        self.humanController:MoveEnd()
        --self:OnEventSetRoleControllerShowState(false)
        -- 停下
        if lookAtPos then
            self.humanCharacter:SmoothDampRotate((lookAtPos - self.followTF.position),0.2)
            coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.2))
        end
        Events.Broadcast("MaidCoffeeFindPathSuccess")
        --self:FindPathSuccess(params)
    end)
end

function MaidCoffeeSceneEnter:GoToPoint(point)
    local curPos = self.followTF.position
    local link = point - curPos
    local num = Vector3.SqrMagnitude(link)
    local num2 = (StopDistance * StopDistance)
    while Vector3.SqrMagnitude(link) > (StopDistance * StopDistance) do
        self.humanController:Move(link.normalized)
        cs_coroutine.yield_return(Yielders.EndOfFrame)
        link = point - self.followTF.position
        num = Vector3.SqrMagnitude(link)
        num2 = (StopDistance * StopDistance)
    end
end

function MaidCoffeeSceneEnter:FindPathSuccess(params)
    CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("MaidCoffeeSceneEnterFindPathSuccess")
    local type = params.type
    local tabIndex = params.tabIndex
    local id = params.id
    local exParams = params.exParams
    local FindPathEndCallBack = {
        [GoToType.MaidCoffee] = function()
            self:OnChangeVirtualCam(Constants.UITypeIds.UIMaidCoffeeManagerDialog)
            coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(MaidCoffeeConstants.VirtualCamTime))
            self:OnRoleStateChange(false,true)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeManagerDialog,parameters = exParams }, {{ id = Constants.UITypeIds.UIMaidCoffeeMainDialog} } )
            if exParams and exParams.dialogId then
                coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.2))
                if exParams.dialogId ==  Constants.UITypeIds.UIMaidCoffeeStatementDialog then
                    UIModule.OpenDialog({ id = exParams.dialogId })
                elseif exParams.dialogId ==  Constants.UITypeIds.UIMaidCoffeePersonMainDialog then
                    --Events.Broadcast("MaidCoffeeChangeVirCam",Constants.UITypeIds.UIMaidCoffeePersonMainDialog)
                    Events.Broadcast("MaidCoffeeTvNodeChangeState",false)
                    coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(0.28))
                    UIModule.OpenDialog({ id =  exParams.dialogId },{{ id = Constants.UITypeIds.UIMaidCoffeeManagerDialog} })
                else
                    UIModule.OpenDialog({ id = exParams.dialogId },{{ id = Constants.UITypeIds.UIMaidCoffeeManagerDialog} })
                end
            end
            MaidCoffeeUtils.MaidCoffeeSetMouseMode(Constants.CameraControlMode.None)
        end,
        
        [GoToType.MaidCoffeeCooking] = function()
            self:OnRoleStateChange(false)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeCookingMainDialog, parameters = { type = MaidCoffeeConstants.CookingType.Cooking,tableIndex = tabIndex ,id = id,cb = function() end } },{{ id = Constants.UITypeIds.UIMaidCoffeeMainDialog} }  )
            MaidCoffeeUtils.MaidCoffeeSetMouseMode(Constants.CameraControlMode.None)
        end,

        [GoToType.MaidCoffeeCat] = function()
            self:SetPlayerDitherIntensity(false)
            MaidCoffeeUtils.MaidCoffeeSetMouseMode(Constants.CameraControlMode.None)
            UIModule.OpenDialog(UIArgs( Constants.UITypeIds.MaidCoffeeCatDrawEntryDialog, {type = 1}), {{id = Constants.UITypeIds.UIMaidCoffeeMainDialog}})
            coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(1))
            self:OnRoleStateChange(false,true)
        end,

        [GoToType.MaidCoffeeCatList] = function()
            self:SetPlayerDitherIntensity(false)
            MaidCoffeeUtils.MaidCoffeeSetMouseMode(Constants.CameraControlMode.None)
            ----猫球养成
            UIModule.OpenDialog(UIArgs(Constants.UITypeIds.OverseaManageCatballControlDialog), { { id = Constants.UITypeIds.UIMaidCoffeeMainDialog } })
            coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(1))
            self:OnRoleStateChange(false,true)
        end,

        [GoToType.MaidCoffeeLounge] = function()
            Events.Broadcast(MaidCoffeeConstants.EventNames.UpdateLoungeSceneShowState, true)
        end
    }
    if FindPathEndCallBack[type] then
        FindPathEndCallBack[type]()
    end
    self.isInGoToCo = false
    self.humanController.canRun = self.curRunMode
    CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("MaidCoffeeSceneEnterFindPathSuccess")
end

function MaidCoffeeSceneEnter:OnChangeVirtualCam(id)
    if not isNull(self.curCam) then
        KTool.SetActive(self.curCam.gameObject,false)
    end
    self.curCam = self:GetVirCamById(id)

    if self.curCam then
        KTool.SetActive(self.curCam.gameObject,true)
    end
end

function MaidCoffeeSceneEnter:OnRoleStateChange(state,isClose)
    if self.playerCharacterNode then
        self:OnEventSetRoleControllerShowState( state )
        KTool.SetActive(self.playerCharacterNode,state)

        if state then
            self:SetPlayerDitherIntensity(true)
        end
    end
    local scenePosNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
    local Maid_loc = scenePosNode.transform:Find("Maid_loc")
    if Maid_loc then
        if isClose then
            KTool.SetActive(Maid_loc,false)
        else
            if state then
                KTool.SetActive(Maid_loc,true)
            end
        end
    end
end

function MaidCoffeeSceneEnter:OnRenovateCamChange(data)
    if not isNull(self.curRenovateCam) then
        KTool.SetActive(self.curRenovateCam.gameObject,false)
    end
    if not isNull(data) then
        local scenePosNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.SceneVirtualCameraNode]
        local pathName = table.concat({"Cam_furniture/",data.Camera})
        local cam = scenePosNode.transform:Find(pathName)
        if not isNull(cam) then
            KTool.SetActive(cam.gameObject,true)
            self.curRenovateCam = cam
        end
    end
end

function MaidCoffeeSceneEnter:OnRenovateSuitChange(data,isSuit,type,isSave)
    if not isNull(data) and table.count(data) > 0 then
        KTool.SetActive(self.showSuitNode.gameObject,true)
        local isNeedSelect = false
        if not isSuit then
            isNeedSelect = true
        end
        self:LoadSuitPrefab(data,isNeedSelect,type,isSave)
    else
        KTool.SetActive(self.showSuitNode.gameObject,false)
        for i, v in pairs(self.typeToNode) do
            if not isNull(v) then
                KTool.SetActive(v,true)
            end
        end
    end
end

function MaidCoffeeSceneEnter:OnClearRenovateState()
    if not isNull(self.drawOutLine) then
        self.drawOutLine:SetTarget(nil)
    end
end

