----倒计时结束 要请求一下事件
function MaidCoffeeSceneEnter:RefreshGuestEvent()
    local isOther = self:IsOther()
    if isOther then
        return
    end
    GameUtils.Request(Interfaces.MaidCoffeeGuestDailyEvent, {}, function(req, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local data = checkTable(response.data)
        ---@type MaidCoffeeComponent
        local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        component:InitialEventDojo(data)
        self:RefreshGuestShow(data.events)
        Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeRefreshGuestEventsComplete)
    end)
end

function MaidCoffeeSceneEnter:RefreshGuestShow(events)
    self:RemoveGuestCo()
    self.refreshGuestCo = cs_coroutine.start(function()
        local mainCamera     = URPCameraController.Instance.mainCamera
        if not isNull(self._nodeName2node) then
            local scenePosNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
            for i, v in pairs(events) do
                if not self.eventGuests[v.eventId] then
                    local pos = self:RandomSingleGuestPos()
                    local posRootName = string.format(MaidCoffeeConstants.GuestPosRootName,pos)
                    local rootGo = scenePosNode.transform:Find(posRootName)
                    assert( rootGo )
                    local guestController = MaidCoffeeGuestController.New()
                    assert( self.followTF )
                    guestController:Init(v, rootGo, self.followTF, self._worldSpaceCanvas,mainCamera,pos)
                    self.eventGuests[v.eventId] = guestController
                end
            end
        end
    end)
end

function MaidCoffeeSceneEnter:GetCacheSuitObject(id)
    local go = nil
    if not self.cacheSuitGos or not self.cacheSuitGos[id] then
        return go
    end

    if self.cacheSuitGos[id] then
        go = self.cacheSuitGos[id]
        self.cacheSuitGos[id] = nil
    end

    return go
end

function MaidCoffeeSceneEnter:PushCacheSuitObject(id,go)
    KTool.SetActive(go,false)
    if not self.cacheSuitGos then
        self.cacheSuitGos = {}
    end
    if table.count(self.cacheSuitGos) >= MaidCoffeeConstants.PoolMaxCount then
        for i, v in pairs(self.cacheSuitGos) do
            if v then
                KTool.SafeDelete(v)
                self.cacheSuitGos[i] = nil
            end
        end
    end
    self.cacheSuitGos[id] = go
end

function MaidCoffeeSceneEnter:LoadSuitPrefab(data,isNeedSelect,selectType,isSave)
    local selectGo = nil
    for i, v in pairs(self.typeToNode) do
        if data[i] then
            local tempGo = self:LoadPartPrefab(data[i],isSave)
            local canSelect = (not isNull(selectType)) and selectType == data[i].furnitureType
            if canSelect then
                selectGo = tempGo
            end
        else
            if self.curTypeSuit[i] then
                self:PushCacheSuitObject(self.curTypeSuit[i].id,self.curTypeSuit[i].go)
                self.curTypeSuit[i] = nil
            end
            KTool.SetActive(v.gameObject,true)
        end
    end
    if selectGo then
        self:RefreshSelect(isNeedSelect,selectGo)
    else
        self:RefreshSelect(false)
    end
end

function MaidCoffeeSceneEnter:LoadPartPrefab(data,isSave)
    local tempGo = nil
    local type = data.furnitureType
    if self.curTypeSuit[type] and data.refId == self.curTypeSuit[type].id then
        tempGo = self.curTypeSuit[type].go
        if isSave then
            self.curTypeSuit[type] = nil
        end
    else
        tempGo = self:GetCacheSuitObject(data.refId)
    end
    ---关掉上一次存的
    if not isNull(self.curTypeSuit[type]) and data.refId ~= self.curTypeSuit[type].id then
        self:PushCacheSuitObject(self.curTypeSuit[type].id,self.curTypeSuit[type].go)
        self.curTypeSuit[type] = nil
    end
    if tempGo then
        kTool.SetActive(tempGo,true)
        if isSave then
            ---这里 还要关掉默认的装扮
            if not isNull(self.typeToNode[type]) then
                CfUtils.SetActive(self.typeToNode[type].gameObject,false)
                CfUtils.SafeDelete(self.typeToNode[type].gameObject)
            end
            KTool.SetParent(tempGo, self.sceneNode.gameObject)
            self.typeToNode[type] = tempGo
        else
            ---替换一下
            self.curTypeSuit[type] = { id = data.refId,go = tempGo }
            ---这里 还要关掉默认的装扮
            if not isNull(self.typeToNode[type]) then
                CfUtils.SetActive(self.typeToNode[type].gameObject,false)
            end
        end
    else
        self:LoadSignCattyPrefab(data,function(_loader)
            tempGo = _loader:Instantiate()
            tempGo.transform.localPosition = Vector3.New(0, 0, 0)
            if isSave then
                ---这里 还要关掉默认的装扮
                if not isNull(self.typeToNode[type]) then
                    CfUtils.SetActive(self.typeToNode[type].gameObject,false)
                    CfUtils.SafeDelete(self.typeToNode[type].gameObject)
                end
                KTool.SetParent(tempGo, self.sceneNode.gameObject)
                self.typeToNode[type] = tempGo
            else
                self.curTypeSuit[type] = { id = data.refId,go = tempGo }
                _loader:Release()
                KTool.SetParent(tempGo, self.showSuitNode.gameObject)
                ---这里 还要关掉默认的装扮
                if not isNull(self.typeToNode[type]) then
                    CfUtils.SetActive(self.typeToNode[type].gameObject,false)
                end
            end
        end)
    end
    return tempGo
end

