function MaidCoffeeSceneEnter:LoadManagerModel()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local id = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    ---检测一下当前位置是否有人 有人的话 就下掉
    local pos = MaidCoffeeConstants.SelectType.Manager * 100 + 1
    if id == 0 then
        if self.personModels and self.personModels[pos] then
            GameObject.Destroy(self.personModels[pos].go)
            self.personModels[pos] = nil
        end
        Events.Broadcast("MaidCoffeeRefreshManagerStatus",true)
        return
    end
    Events.Broadcast("MaidCoffeeRefreshManagerStatus",false)
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(id)
    if not isNull(cardDojo) then
        local cardInfoVo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
        local timeLineId = cardInfoVo.timeLineId[1] ---店长只有一个位置  不用随机
        local offsetY = cardInfoVo.coordinate
        local name = MaidCoffeeUtils.GetMaidCoffeePersonAniVo(timeLineId).point
        if not self.cacheModelPos[name] then
            local scenePosNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
            self.cacheModelPos[name] = scenePosNode.transform:Find(name)
        end
        ---说明位置上有人
        if self.personModels[pos] then
            ---ID如果一样 不处理
            if  self.personModels[pos].id ~= id then
                GameObject.Destroy(self.personModels[pos].go)
                self.personModels[pos] = nil
                ---再上新的人
                self:LoadPrefabById(id,pos,name,offsetY,cardInfoVo.cloudPoint,cardDojo)
            end
        else
            self:LoadPrefabById(id,pos,name,offsetY,cardInfoVo.cloudPoint,cardDojo)
        end
    end
end

function MaidCoffeeSceneEnter:LoadPrefabById(id,pos,posName,offsetY,cloudPath,cardDojo)
    ---没人的时候 把这个人放上去
    local path = MaidCoffeeUtils.GetCardModelPathById(cardDojo)
    ResourceModule.LoadBundleAsync(path, function(_loader, isOk, resultObject)
        if isOk then
            local managerModelGo = _loader:Instantiate()
            KTool.SetParent(managerModelGo,self.cacheModelPos[posName].gameObject,false)
            KTool.GetOrAddComponent(managerModelGo.gameObject,typeof(CS.CustomLightDirRelativeCamera))
            managerModelGo.transform.localPosition = Vector3(managerModelGo.transform.localPosition.x, managerModelGo.transform.localPosition.y + offsetY, managerModelGo.transform.localPosition.z)
            self.personModels[pos] = {id = id , go = managerModelGo}
            ---绑定动画状态机
            self:LoadAnimatorControllerAndFillController(id,managerModelGo,cardDojo)

            local isOther = self:IsOther()
            if isOther then
                return
            end
            self:LoadCloudById(id,managerModelGo,cloudPath)
            self:PlayRoleAni(cardDojo)
        end
    end)
end

function MaidCoffeeSceneEnter:PlayRoleAni(cardDojo,needPlay)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local id = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    if id ~= 0 and not isNull(self.curAnimator) then
        ---设置心情值和状态 会刷新
        local point = tonumber(cardDojo.cafeEnergy) or 0
        if point > 0 then
            if needPlay then
                local time = os.time()
                if time >= checkNumber(self.coldTime) then
                    self.curAnimator:SetInteger("action",1)
                    self.coldTime = os.time() + 60
                    self:RemoveWaitCo()
                    self.waitCo = cs_coroutine.start(function()
                        coroutine.yield(Yielders.EndOfFrame)
                        self.curAnimator:SetInteger("action",0)
                    end)
                end
            end
        else
            if point == 0 then
                self.curAnimator:SetInteger("action",2)
            end
        end
    end
end

function MaidCoffeeSceneEnter:LoadCloudById(id,go,cloudPath)
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComponent:GetCardById(tonumber(id))
    ---设置心情值和状态 会刷新
    local point = tonumber(cardDojo.cafeEnergy) or 0
    if point == 0 then
        local parent = go.transform:Find(cloudPath)
        if not isNull(parent) then
            if not self.cloudPrefabs[id] then
                ResourceModule.LoadBundleAsync(MaidCoffeeConstants.CloudRainPath, function(_loader, isOk, resultObject)
                    if isOk then
                        local cloudPrefab = _loader:Instantiate()
                        KTool.SetParent(cloudPrefab.gameObject,parent.gameObject,false)
                        cloudPrefab.transform.localPosition = Vector3.New(-0.12,0,0)
                        self.cloudPrefabs[id] = cloudPrefab
                    end
                end)
            else
                KTool.SetParent(self.cloudPrefabs[id].gameObject,parent.gameObject,false)
            end
        end
    else
        if self.cloudPrefabs[id] then
            KTool.SafeDelete(self.cloudPrefabs[id].gameObject)
            self.cloudPrefabs[id] = nil
        end
    end
end

function MaidCoffeeSceneEnter:LoadClerkModel()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    for i = 1, 3 do
        local id = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
        local pos = MaidCoffeeConstants.SelectType.Clerk * 100 + i
        if id == 0 then
            if self.personModels and self.personModels[pos] then
                self:ClearPosTimeLine(pos)
            end
        else
            ---有人 看一下当前是不是同一个
            if self.personModels[pos] then
                if self.personModels[pos].id ~= id then
                    self:ClearPosTimeLine(pos)
                    self:LoadTimeLineById(id,pos)
                end
            else
                self:LoadTimeLineById(id,pos)
            end
        end
    end
end

function MaidCoffeeSceneEnter:LoadCatModel()
    local scenePosNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
    local catNode = scenePosNode.transform:Find(MaidCoffeeConstants.SceneDefine.CatNodeName)
    MaidCoffeeMgr:GetInstance():StartLoadCat(catNode)
end

function MaidCoffeeSceneEnter:InitMainCamSetting()
    local mainCamera     = URPCameraController.Instance.mainCamera

    local loader = ResourceModule.LoadBundleAsync(MaidCoffeeConstants.DrawOccupiedMatPath, nil, true)
    while not loader.IsCompleted do
        coroutine.yield(Yielders.EndOfFrame)
    end

    if loader.IsSuccess then
        self.drawOutLine = KTool.GetOrAddComponent(mainCamera.gameObject,typeof(DrawOutlineEffect))
        self.drawOutLine.enabled = true
        local mat = GameObject.Instantiate(loader.ResultObject)
        self.drawOutLine.OccupiedMaterial = mat
        self.effectMat = mat
    end
end

function MaidCoffeeSceneEnter:ResetMainCamSetting()
    local mainCamera      = URPCameraController.Instance.mainCamera
    KTool.SafeDelete(self.effectMat)
    CfUtils.DelCompoent(mainCamera, typeof(DrawOutlineEffect))
    self.drawOutLine = nil
end

function MaidCoffeeSceneEnter:ClearPosTimeLine(pos)
    GameObject.Destroy(self.personModels[pos].go)
    self.personModels[pos] = nil
    self.usedTimeLineIds[self.posToTimeLineId[pos]] = nil
    self.posToTimeLineId[pos] = nil
end

function MaidCoffeeSceneEnter:LoadTimeLineById(id,pos,cardData)
    ---先随机一个位置 位置要从动画表中找 所以要先查出对应timeLineId列表 然后随机出一个timelineId
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(id)
    if isNull(cardDojo) and not isNull(cardData) then
        cardDojo = CardDojo.New()
        cardDojo:Fill(cardData)
    end

    if not isNull(cardDojo) then
        local cardInfoVo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
        if cardInfoVo then
            local timeLineId,index = self:GetRandomTimeLineId(cardInfoVo.timeLineId,id,pos)
            if timeLineId then
                local tineLineVo = MaidCoffeeUtils.GetMaidCoffeePersonAniVo(timeLineId)
                local name = string.format("Maid_loc/%s",tineLineVo.point)
                if not self.cacheModelPos[name] then
                    local scenePosNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
                    self.cacheModelPos[name] = scenePosNode.transform:Find(name)
                end
                local tlGo = self:BindTimeLineAndPlay(tineLineVo.timeLine,self.cacheModelPos[name].gameObject,cardInfoVo.cardId)
                if not isNull(tlGo) then
                    local clerkGo = tlGo.transform:Find(string.format("%s_lobby",cardInfoVo.cardId))
                    if clerkGo then
                        if checkNumber(index) > 0 then
                            local isLookAt = checkNumber(cardInfoVo.hasLookAt[index]) == 1
                            local LookAtIKType = clerkGo.gameObject:EnsureComponent(LookAtIKType)
                            local needLookAt = tineLineVo.hasLookAt
                            if isLookAt and needLookAt then
                                if LookAtIKType then
                                    LookAtIKType.enabled = true
                                end
                            else
                                if LookAtIKType then
                                    LookAtIKType.enabled = false
                                end
                            end
                        end
                        self.personModels[pos] = {id = id,go = tlGo,clerkGo = clerkGo}
                    else
                        self.personModels[pos] = {id = id,go = tlGo}
                    end
                end
            end
        end
    end
end

function MaidCoffeeSceneEnter:BindTimeLineAndPlay(timeLineName,go,cardId)
    local path = string.format('Timeline/Prefab/maidcafe/%s/%s.prefab',cardId ,timeLineName)
    local tlGo = GameUtils.LoadBundleAsync(path, go, false, true)
    if not isNull(tlGo) then
        KTool.SetLayer( go, tlGo.gameObject, true)
        KTool.GetOrAddComponent(tlGo.gameObject,typeof(CS.CustomLightDirRelativeCamera))
        local navMeshObstacle = KTool.GetOrAddComponent(tlGo.gameObject,typeof(CS.UnityEngine.AI.NavMeshObstacle))
        navMeshObstacle.carving = true
        local playableDirector = tlGo:GetComponentInChildren(PlayableDirectorType)
        --playableDirector.playOnAwake = false
        GachaponUtils.BindTimeline(playableDirector, 'role', go)
        KTool.SetActive(go, true)
        --playableDirector:Play()
        return tlGo
    end
    return nil
end

function MaidCoffeeSceneEnter:GetRandomTimeLineId(timeLineIds,id,pos)
    local isNotFind = true
    local timeLineId
    local index
    while isNotFind do
        local randomIndex = math.random(1,table.count(timeLineIds))
        local timeId = timeLineIds[randomIndex]
        if not self.usedTimeLineIds[timeId] then
            timeLineId = timeId
            index = randomIndex
            self.usedTimeLineIds[timeId] = { id = id ,timeLineId = timeId}
            ---用来保存当前pos使用的timelineID
            self.posToTimeLineId[pos] = timeLineId
            isNotFind = false
        end
    end
    return timeLineId,index
end

---场景中的假客人  进场景加载一次
function MaidCoffeeSceneEnter:LoadGuestModel()
    local posS = self:RandomGuestPos()
    local scenePosNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
    local index = 1
    for i, v in pairs(posS) do
        local posRootName = string.format(MaidCoffeeConstants.GuestPosRootName,i)
        local rootGo = scenePosNode.transform:Find(posRootName)
        local prefabPath = string.format(MaidCoffeeConstants.GuestPath,index)
        ---不要和店员ID冲突 方便到时候一起删除
        local pos = 9000 + index
        index = index + 1
        local _go = GameUtils.LoadBundleAsync(prefabPath, rootGo.gameObject, false)
        self.personModels[pos] = {go = _go }
    end
end

function MaidCoffeeSceneEnter:LoadBusinessModel()
    self:CleanBusinessModel()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local data = maidCoffeeHomeDojo:GetMerchantData()
    if not isNull(data.merchant) and next(data.merchant) then
        local scenePosNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
        local rootGo = scenePosNode.transform:Find(MaidCoffeeConstants.BusinessPosNodeName)
        local mainCamera     = URPCameraController.Instance.mainCamera
        local businessController = MaidCoffeeBusinessController.New()
        businessController:Init(rootGo,self.followTF,self._worldSpaceCanvas,mainCamera)
        self.businessCtr = businessController
    end
end

function MaidCoffeeSceneEnter:LoadEventGuestModel()
    ---@type MaidCoffeeComponent
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local events = maidCoffeeComponent:GetAllEvents()
    local mainCamera     = URPCameraController.Instance.mainCamera
    if  isNull(self._nodeName2node) or isNull(self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]) then
        self.isNeedRefresh = true
        return
    end
    local scenePosNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
    for i, v in pairs(events) do
        local pos = self:RandomSingleGuestPos()
        local posRootName = string.format(MaidCoffeeConstants.GuestPosRootName,pos)
        local rootGo = scenePosNode.transform:Find(posRootName)
        local guestController = MaidCoffeeGuestController.New()
        guestController:Init(v,rootGo,self.followTF,self._worldSpaceCanvas,mainCamera,pos)
        self.eventGuests[v.eventId] = guestController
    end
end


function MaidCoffeeSceneEnter:DoShowWorldSpaceCanvas(isShow)
    if not isNull(self._worldSpaceCanvas) then
        KTool.SetActive(self._worldSpaceCanvas.gameObject, isShow == true )
    end
end

---获取一个随机位置
function MaidCoffeeSceneEnter:RandomSingleGuestPos()
    if not self.cachePos then
        self.cachePos = {}
    end
    local pos = nil
    while isNull(pos) do
        local tempPos = math.random(1,8)
        if  not self.cachePos[tempPos] then
            self.cachePos[tempPos] = true
            pos = tempPos
        end
    end
    return pos
end

---RandomGuestPos
---随机出4个位置 给场景的假顾客
function MaidCoffeeSceneEnter:RandomGuestPos(count)
    local cachePos = {}
    while table.count(cachePos) < count do
        local pos = math.random(1,14)
        if  not cachePos[pos] then
            cachePos[pos] = true
        end
    end
    return cachePos
end

---GetVirCamById
---
---id 对应的UI的dialogId 用来判定当前UI要切换到那个相机
function MaidCoffeeSceneEnter:GetVirCamById(id)
    local camNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.SceneVirtualCameraNode]
    if not self.camCache then
        self.camCache = {}
    end
    if not self.camCache[id] then
        if id == Constants.UITypeIds.UIMaidCoffeeManagerDialog then
            self.camCache[id] = camNode.transform:Find("MaidCam_loc/Cam_BarMiddle").gameObject
        elseif id == Constants.UITypeIds.UIMaidCoffeePersonMainDialog then
            self.camCache[id] = camNode.transform:Find("MaidCam_loc/Cam_BarClose").gameObject
        end
    end
    return self.camCache[id]
end

