--- InitBehaviorAction
---@param role UnityEngine.GameObject
function MaidCoffeeSceneEnter:InitBehaviorAction(role)
    ---@type Engine.Lib.BehaviourAction
    local behaviorAction            = KTool.GetOrAddComponent(role.gameObject, BehaviourActionType)
    behaviorAction.UpdateAction     = Bind(self, self.OnUpdateAction)
    behaviorAction.LateUpdateAction = Bind(self, self.OnLateUpdateAction)
    self._behaviorAction            = behaviorAction
end

function MaidCoffeeSceneEnter:OnUpdateAction()
    if not self._isLoadComplete then return end
    local curRolePosition = self.followTF.position
    local isMove = Vector3.Distance(curRolePosition, self._lastRolePosition) > 0.0001
    self.isMove = isMove
    if isMove then
        self._lastRolePosition = curRolePosition
        self:UpdateManageAction()
        self:UpdateClerkAction()
        self:UpdateCatAction()
    end
end

function MaidCoffeeSceneEnter:UpdateCatAction()
    local allCats =  MaidCoffeeMgr:GetInstance():GetCats()
    if table.count(allCats) <= 0 then return end

    for i, v in pairs(allCats) do
        local dis = Vector3.Distance(self.followTF.position, v.transform.position)
        if dis <= MaidCoffeeConstants.CatDistance then
            local roleAngle = CS.UnityEngine.Vector3.Angle(self.followTF.forward, v.transform.forward)
            if roleAngle <= 30 and not v.Env:GetRunStatus() then
                v.Env:RunAway()
            else
                v.Env:SetRunStatus(false)
            end
        end
    end
end

function MaidCoffeeSceneEnter:UpdateManageAction()
    local isOther = self:IsOther()
    if isOther then
        return
    end
    ---检测一下当前位置是否有人
    local pos = MaidCoffeeConstants.SelectType.Manager * 100 + 1
    if not isNull(self.personModels[pos]) then
        local go = self.personModels[pos].go
        local dis = Vector3.Distance(self.followTF.position, go.transform.position)
        local roleAngle = MaidCoffeeUtils.CalcAngleAndClockwise(self.followTF.forward, go.transform.position, self.followTF.position)
        if dis <= MaidCoffeeConstants.BowDistance and roleAngle <= 120 then
            local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            local id = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
            local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
            local cardDojo = cardComponent:GetCardById(tonumber(id))
            self:PlayRoleAni(cardDojo,true)
        end
    end
end

function MaidCoffeeSceneEnter:UpdateClerkAction()
    ---@type MaidCoffeeComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    for i = 1, 3 do
        local id = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
        if id ~= 0 then
            local pos = MaidCoffeeConstants.SelectType.Clerk * 100 + i
            local go = not isNull(self.personModels[pos]) and self.personModels[pos].clerkGo or nil
            if not isNull(go) then
                local dis = Vector3.Distance(self.followTF.position, go.transform.position)
                --local roleAngle = MaidCoffeeUtils.CalcAngleAndClockwise(self.followTF.forward, go.transform.position, self.followTF.position)
                local lookAtController = go.gameObject:EnsureComponent(LookAtControllerType)
                if dis <= MaidCoffeeConstants.LookAtDistance then
                    if lookAtController then
                        lookAtController.target = self.humanHeadTF
                    end
                else
                    if lookAtController then
                        lookAtController.target = nil
                    end
                end
            end
        end
    end
end

function MaidCoffeeSceneEnter:RemoveWaitCo()
    if not isNull(self.waitCo) then
        cs_coroutine.stop(self.waitCo)
        self.waitCo = nil
    end
end

function MaidCoffeeSceneEnter:OnLateUpdateAction()
    if not self._isLoadComplete then return end
    local nearData = {}
    for i, v in pairs(self.eventGuests) do
        v:FreshBubbleNodePosition()
        local isNear = v:IsNearGuest()
        if isNear then
            table.insert(nearData, {type = MaidCoffeeConstants.OptionType.Guest, data = v})
        end
    end

    if not isNull(self.businessCtr) then
        self.businessCtr:FreshBubbleNodePosition()
        local isNear = self.businessCtr:IsNear()
        if isNear then
            table.insert(nearData, {type = MaidCoffeeConstants.OptionType.Business,data = nil})
        end
    end

    Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeRefreshNearTip,nearData)
end

function MaidCoffeeSceneEnter:FreshLocationCam(status,type,eventsId)
    KTool.SetActive(self.virtualCamera.gameObject,status)
    if status then
        if type == MaidCoffeeConstants.OptionType.Guest then
            local eventGuest = self.eventGuests[eventsId]
            if eventGuest and not isNull(eventGuest.guestGo) then
                self:SetLocationCam(eventGuest.guestGo)
            end
        elseif type == MaidCoffeeConstants.OptionType.Business then
            self:SetLocationCam(self.businessCtr.businessGo)
        end
    end
end

function MaidCoffeeSceneEnter:SetLocationCam(npcTarget)
    local mainCamera     = URPCameraController.Instance.mainCamera
    local transform      = mainCamera.transform
    local cameraPos      = transform.position
    local protagonist    = self.followTF
    local protagonistPos = protagonist.position
    local npcPos         = npcTarget.transform.position
    -- 现在 protagonistPos 和 npcPos y值都接近 0

    --- 向量 相机_主角
    local camera2role = CS.UnityEngine.Vector3(protagonistPos.x - cameraPos.x, 0.0, protagonistPos.z - cameraPos.z)
    --- 向量 主角_NPC
    local role2npc    = CS.UnityEngine.Vector3(npcPos.x - protagonistPos.x, 0.0, npcPos.z - protagonistPos.z)

    -- angle: [0,180]
    -- clockwise: c位于右侧为 1, 位于左侧为 -1
    local angle, clockwise   = MaidCoffeeUtils.CalcAngleAndClockwiseByVector(camera2role, role2npc)

    local virtualCamera = self.virtualCamera -- "LocationVirtualCamera"

    -- 夹角小于 angleThreshold 时, 需要将夹角扩大到 tgtThreshold:
    local angleThreshold = 30.0
    local tgtThreshold = 35.0

    local centerPos = (npcPos + protagonistPos) * 0.5
    centerPos.y = 1 -- 不要看向地面;

    local vecLen = (centerPos - cameraPos).magnitude -- 保持向量长度
    vecLen = vecLen + 0.2 -- 适当变远
    local tgtPos = cameraPos

    if  ( angle <= angleThreshold and clockwise > 0.0 ) or ( angle >= (180.0-angleThreshold) and clockwise < 0.0 ) then
        --printInfo("逆时针旋A")
        local rot = CS.UnityEngine.Quaternion.Euler( 0.0, -tgtThreshold, 0.0 )
        local newvec = rot * (-1.0 * clockwise * role2npc.normalized)
        tgtPos = centerPos + newvec * vecLen
    elseif ( angle <= angleThreshold and clockwise < 0.0 ) or ( angle >= (180.0-angleThreshold) and clockwise > 0.0 ) then
        --printInfo("顺时针旋B")
        local rot = CS.UnityEngine.Quaternion.Euler( 0.0, tgtThreshold, 0.0 )
        local newvec = rot * (clockwise * role2npc.normalized)
        tgtPos = centerPos + newvec * vecLen
    end

    tgtPos.y = cameraPos.y -- 保持相机高度
    virtualCamera.transform.position = tgtPos

    virtualCamera.transform:LookAt( centerPos )
end
---------------------------------------------------
--- clear end ---
---------------------------------------------------


function MaidCoffeeSceneEnter:RegisterInputFunc()
    local KeyboardInputMap = KeyboardInputMap:GetInstance()

    local playerInputSwitcher = GlobalsInDreamSpace.FindComponent("playerInputSwitcher")
    local CursorLockMode = CS.UnityEngine.CursorLockMode
    local Cursor = CS.UnityEngine.Cursor
    if playerInputSwitcher then

        KeyboardInputMap:RegisterInput(KeyboardInfo.PcTipsKey, function ()
            Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeOpenPcTips)
        end)

        KeyboardInputMap:RegisterInput(KeyboardInfo.LeftCtrl, function ()
            self.isWalking = not self.isWalking
            GameUtils.Toast((self.isWalking == true) and localize("已切换至走路状态") or localize("已切换至跑步状态"))
            if self.isWalking == true then 
                InputManager.SetMoveInputMagnitudeConstraint( nil, 0.2 ) -- 只能走路
            else 
                InputManager.SetMoveInputMagnitudeConstraint( 0.0, 1.0 ) -- 解除 "只能走路" 的限制
            end 
        end)

    end
    
end

function MaidCoffeeSceneEnter:UnRegisterInputFunc()
    local KeyboardInputMap = KeyboardInputMap:GetInstance()

    KeyboardInputMap:UnRegisterInput(KeyboardInfo.PcTipsKey)
    KeyboardInputMap:UnRegisterInput(KeyboardInfo.LeftCtrl)
end

function MaidCoffeeSceneEnter:StartLoadOtherHome()
    self:ResetPlayPos()
    self:LoadOtherCattyPrefab()
    self:LoadCatModel()
    self:LoadBusinessModel()
    self:CleanEventGuestModel()
    self:LoadEventGuestModel()
    self:LoadOtherManagerModel()
    self:LoadOtherClerkModel()
    ---@type MaidCoffeeComponent
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    component:SetIsLoadOtherHomeState(true)
end

function MaidCoffeeSceneEnter:CleanEventGuestModel()
    for i, v in pairs(self.eventGuests) do
        v:Delete()
    end
    self.eventGuests = {}
    self.cachePos = {}
end

function MaidCoffeeSceneEnter:LoadOtherCattyPrefab()
    ---@type MaidCoffeeComponent
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local List = maidCoffeeComponent:GetSaveCattyRenovatedList()
    local data = {}
    for i, v in pairs(List) do
        local vo = MaidCoffeeUtils.GetRenovateInfoVo(v)
        table.insert(data,vo)
    end
    self:LoadSuitPrefab(data,false)
    KTool.SetActive(self.showSuitNode.gameObject,true)
end

function MaidCoffeeSceneEnter:ResetPlayPos()
    local ScenePositionsNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
    local playerPosNode = ScenePositionsNode.transform:Find(MaidCoffeeConstants.SceneDefine.SpawnMarker)
    self.playerCharacterNode.position = playerPosNode.position
    self.humanCharacter:SetRotation(Quaternion.Euler(0,180,0))
    self.playerVCam3rdPersonFollowController:SetLookDirectionImmediately( self.initLookDir )
end

---因为自己可能没有这个人 所以不能共用
function MaidCoffeeSceneEnter:LoadOtherManagerModel()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local cardData = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Manager ,1)
    ---检测一下当前位置是否有人 有人的话 就下掉
    local pos = MaidCoffeeConstants.SelectType.Manager * 100 + 1
    local cardData = checkTable(cardData)
    if not next(cardData) then
        if self.personModels and self.personModels[pos] then
            GameObject.Destroy(self.personModels[pos].go)
            self.personModels[pos] = nil
        end
        return
    end
    local id = cardData.id
    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(id)
    if isNull(cardDojo) then
        ---@type CardDojo
        cardDojo = CardDojo.New()
        cardDojo:Fill(cardData)
    end

    if not isNull(cardDojo) then
        local cardInfoVo = MaidCoffeeUtils.GetCardManagerInfoVo(cardDojo.cardId)
        local timeLineId = cardInfoVo.timeLineId[1] ---店长只有一个位置  不用随机
        local offsetY = cardInfoVo.coordinate
        local name = MaidCoffeeUtils.GetMaidCoffeePersonAniVo(timeLineId).point
        if not self.cacheModelPos[name] then
            local scenePosNode = self._nodeName2node[MaidCoffeeConstants.SceneDefine.ScenePositionsNode]
            self.cacheModelPos[name] = scenePosNode.transform:Find(name)
        end
        ---说明位置上有人
        if self.personModels[pos] then
            ---ID如果一样 不处理
            if  self.personModels[pos].id ~= id then
                GameObject.Destroy(self.personModels[pos].go)
                self.personModels[pos] = nil
                ---再上新的人
                self:LoadPrefabById(id,pos,name,offsetY,cardInfoVo.cloudPoint,cardDojo)
            end
        else
            self:LoadPrefabById(id,pos,name,offsetY,cardInfoVo.cloudPoint,cardDojo)
        end
    end
end

function MaidCoffeeSceneEnter:LoadOtherClerkModel()
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    for i = 1, 3 do
        local cardData = component:GetStaffInfoByType(MaidCoffeeConstants.SelectType.Clerk ,i)
        local cardData = checkTable(cardData)
        local pos = MaidCoffeeConstants.SelectType.Clerk * 100 + i
        local id = cardData.id
        if not next(cardData) then
            if self.personModels and self.personModels[pos] then
                self:ClearPosTimeLine(pos)
            end
        else
            ---有人 看一下当前是不是同一个
            if self.personModels[pos] then
                if self.personModels[pos].id ~= id then
                    self:ClearPosTimeLine(pos)
                    self:LoadTimeLineById(id,pos,cardData)
                end
            else
                self:LoadTimeLineById(id,pos,cardData)
            end
        end
    end
end

function MaidCoffeeSceneEnter:IsOther()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    ---如果是在别人家里  不刷新
    local isOther = maidCoffeeHomeDojo:IsOther()
    return isOther
end

function MaidCoffeeSceneEnter:BackHome()
    self:ResetPlayPos()
    self:LoadSuitPrefab({},false)
    self:LoadCatModel()
    self:LoadBusinessModel()
    self:CleanEventGuestModel()
    self:LoadEventGuestModel()
    self:LoadManagerModel()
    self:LoadClerkModel()
end

function MaidCoffeeSceneEnter:CleanBusinessModel()
    if not isNull(self.businessCtr) then
        self.businessCtr:Delete()
        self.businessCtr = nil
    end
end

return MaidCoffeeSceneEnter
